function crossSection(){pause();let h=state.sim.history.at(-1),level=h?.levels[gauge]||4.8,limit=h?.limits[gauge]||6.8;const y=v=>170-v*15;openModal('DWARSPROFIEL','<h2>'+M.gauges[gauge].name+'</h2><p>Schematisch dwarsprofiel: de rivier krijgt bij hoogwater ruimte in de uiterwaarden. Geen gemeten profiel van deze plaats.</p><svg viewBox="0 0 620 210" role="img" aria-label="Schematisch zomerbed, uiterwaarden en winterdijken"><rect width="620" height="210" fill="#f0f5ed"/><path d="M0 115 L75 115 L100 55 L125 115 L235 115 L260 160 L360 160 L385 115 L495 115 L520 55 L545 115 L620 115 L620 210 L0 210Z" fill="#bbcca5" stroke="#729071"/><path d="M125 '+y(level)+'H495V115H385L360 160H260L235 115H125Z" fill="#4da8c4" opacity=".6"/><line x1="70" x2="550" y1="'+y(limit)+'" y2="'+y(limit)+'" stroke="#b36d39" stroke-dasharray="6 4"/><text x="310" y="190" text-anchor="middle" font-size="14">Zomerbed</text><text x="175" y="100" text-anchor="middle" font-size="13">Uiterwaard</text><text x="438" y="100" text-anchor="middle" font-size="13">Uiterwaard</text><text x="100" y="35" text-anchor="middle" font-size="13">Winterdijk</text><text x="520" y="35" text-anchor="middle" font-size="13">Winterdijk</text></svg><p>Modelwaterstand: '+fmt(level,2)+' m. Beschermingsgrens: '+fmt(limit,2)+' m. Meer ruimte kan de waterstand verlagen; een hogere dijk verhoogt alleen de beschermingsgrens.</p>');}
$('layerControls').innerHTML=Object.entries(layerNames).map(([key,name])=>'<label class="layer"><input type="checkbox" data-layer="'+key+'" '+(layers[key]?'checked':'')+'> '+name+'</label>').join('');document.querySelectorAll('[data-layer]').forEach(c=>c.onchange=()=>toggleLayer(c.dataset.layer,c.checked));
$('playBtn').onclick=play;$('stepBtn').onclick=()=>{pause();tick();};$('speed').onchange=()=>{if(state.running){pause();play();}};$('qTab').onclick=()=>{metric='q';drawChart();};$('hTab').onclick=()=>{metric='h';drawChart();};$('rainTab').onclick=()=>{metric='rain';drawChart();};$('gaugeSelect').onchange=e=>{gauge=+e.target.value;drawChart();};$('sectionBtn').onclick=crossSection;$('regionBtn').onclick=()=>map?.setView([51.0,5.6],7);$('nlBtn').onclick=()=>map?.fitBounds([[50.7,3.25],[53.65,7.3]]);$('refreshBtn').onclick=resetSituation;$('resetBtn').onclick=resetSituation;$('helpBtn').onclick=glossary;$('glossaryBtn').onclick=glossary;$('sourcesBtn').onclick=sourcesModal;$('scoresBtn').onclick=highscores;$('scenarioBtn').onclick=scenarioMenu;$('briefingBtn').onclick=briefing;$('financeBtn').onclick=financeMenu;$('legendBtn').onclick=mapLegend;$('effectsBtn').onclick=()=>explainPlan(false);
