waveMotion=!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;initMap();syncLayers();render();if(new URLSearchParams(location.search).get('menu')==='campaign')campaign();else if(new URLSearchParams(location.search).get('menu')==='missions')scenarioMenu();else if(new URLSearchParams(location.search).get('menu')==='duel')setupDuel();else briefing();
const context=document.modelContext;if(context?.registerTool){try{context.registerTool({name:'read_water_game',description:'Read the current Maas mission, plan, budget and simulated water levels.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode,scenario,hour:state.sim.t,plan:state.plan,budget:budget(),finance:funds(),latest:state.sim.history.at(-1)||null})});context.registerTool({name:'inspect_maas_location',description:'Select a location and reveal the specified educational map layers. Does not purchase a measure.',inputSchema:{type:'object',properties:{areaId:{type:'string'},layers:{type:'array',items:{type:'string'}}},required:['areaId','layers'],additionalProperties:false},execute:input=>{if(!D.areas.some(a=>a.id===input.areaId)||!Array.isArray(input.layers)||input.layers.some(k=>!Object.hasOwn(layers,k)))throw Error('Onbekende locatie of kaartlaag.');selectArea(input.areaId);input.layers.forEach(k=>toggleLayer(k,true));return {area:area(),seen:state.seen[selected]};}});context.registerTool({name:'place_maas_measure',description:'Purchase a measure within the available budget. Location research is optional; poor fit reduces effectiveness or support.',inputSchema:{type:'object',properties:{areaId:{type:'string'},measureId:{type:'string'},packageId:{type:'string'}},required:['areaId','measureId','packageId'],additionalProperties:false},execute:input=>{place(input.areaId,input.measureId,input.packageId);return {plan:state.plan,budget:budget(),finance:funds()};}});}catch{console.info('Optional browser tools unavailable');}}
